CREATE OR REPLACE FUNCTION private.area_go(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare p player;
begin
  select * into p from player where world_id = p_world and uid = p_uid;
