  perform set_config('wildermon.uid', '', true);
  perform set_config('wildermon.go_at', '', true);
  perform set_config('wildermon.pk', '', true);
  perform set_config('wildermon.pk_act', '', true);
  perform set_config('wildermon.floor', '', true);
end $function$
